import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {ToolRegistry} from './tools/registry.js';
import type {ToolResponse} from './tools/registry.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {q: 'x'}}};
const STOP_FOR_TOOL: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
const STOP_FOR_TOOL_WITH = (usage: UsageMetadata): MessageChunk => ({type: 'stop', stopReason: 'tool_use', usage});
const STOP_DONE_WITH = (usage: UsageMetadata): MessageChunk => ({type: 'stop', stopReason: 'end_turn', usage});

const createSession = (content: string): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content, timestamp: '2026-01-01T00:00:00.000Z'}],
});

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;

  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      for (const chunk of rounds[round++] ?? []) yield chunk;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const registryReturning = (response: ToolResponse): ToolRegistry => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'lookup', description: 'looks things up', inputSchema: {type: 'object'}},
    async () => response
  );
  return registry;
};

const usageReportedToHook = async (rounds: MessageChunk[][]): Promise<UsageMetadata | undefined> => {
  let reported: UsageMetadata | undefined;
  const hooks: OrchestratorHooks = {
    afterModelResponse: async (_session, _text, usage) => {
      reported = usage;
    },
  };
  const orchestrator = createChatOrchestrator(
    scriptedProvider(rounds),
    promptBuilder,
    registryReturning({result: 'r'}),
    {
      hooks,
    }
  );

  await orchestrator.processMessage(createSession('ask'));
  return reported;
};

describe('afterModelResponse usage across tool rounds', () => {
  it('reports 660 total tokens for a turn of two tool rounds and a final answer', async () => {
    const reported = await usageReportedToHook([
      [TOOL_CALL, STOP_FOR_TOOL_WITH({inputTokens: 100, outputTokens: 10, totalTokens: 110})],
      [TOOL_CALL, STOP_FOR_TOOL_WITH({inputTokens: 200, outputTokens: 20, totalTokens: 220})],
      [{type: 'text', text: 'done'}, STOP_DONE_WITH({inputTokens: 300, outputTokens: 30, totalTokens: 330})],
    ]);

    expect(reported).toEqual({inputTokens: 600, outputTokens: 60, totalTokens: 660});
  });

  it('sums the rounds that reported to 60 tokens and reports undefined when no round reported', async () => {
    const partiallyReported = await usageReportedToHook([
      [TOOL_CALL, STOP_FOR_TOOL_WITH({inputTokens: 10, outputTokens: 5, totalTokens: 15})],
      [TOOL_CALL, STOP_FOR_TOOL],
      [{type: 'text', text: 'done'}, STOP_DONE_WITH({inputTokens: 30, outputTokens: 15, totalTokens: 45})],
    ]);
    const unreported = await usageReportedToHook([
      [TOOL_CALL, STOP_FOR_TOOL],
      [
        {type: 'text', text: 'done'},
        {type: 'stop', stopReason: 'end_turn'},
      ],
    ]);

    expect({partiallyReported, unreported}).toEqual({
      partiallyReported: {inputTokens: 40, outputTokens: 20, totalTokens: 60},
      unreported: undefined,
    });
  });
});

